struct future { pthread_mutex_t m; pthread_cond_t cv; int ready, failed; int value; };

int future_get(struct future *f, int ms) {            /* blocking read end */
    pthread_mutex_lock(&f->m);
    while (!f->ready)
        if (wait_ms(&f->cv, &f->m, ms)) {             /* helper: timed wait */
            pthread_mutex_unlock(&f->m);
            return ETIMEDOUT;
        }
    int v = f->failed ? -1 : f->value;                /* published once, read many */
    pthread_mutex_unlock(&f->m);
    return v;
}
/* producer: lock, store value, f->ready = 1, unlock, pthread_cond_signal(&f->cv); */

static void after_work(uv_work_t *req, int status) {   /* value is ready */
    struct job *j = req->data;
    if (status == 0)
        apply_result(j);      /* continuation, runs on the loop thread */
    else
        report(j->err);
}

struct job *j = start_job(arg);            /* pending value: slot + status */
uv_queue_work(uv_default_loop(), &j->req, do_work, after_work);

